import { DetailsCardItem } from '@getvim/atomic-ui';
import React, { FC } from 'react';
import './index.less';

interface UserManagementInfoFieldProps {
  value?: string;
  svgIcon: string;
  label?: string;
}

export const UserManagementInfoField: FC<UserManagementInfoFieldProps> = ({
  svgIcon,
  value,
  label,
}) => {
  const fallBackValue = '-';

  return (
    <div className="management-user-field">
      <img src={svgIcon} />
      <DetailsCardItem label={label} value={value || fallBackValue} />
    </div>
  );
};
